From c1f70d7a5f4409bda0a4e0a85917982769bb5205 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:23:04 +0100
Subject: [PATCH] applets/taskmanager: forward other drops on empty space to
 the panel

Dropping a document or link on an empty part of the task manager did
nothing. Now it is handed to the containment like a drop on the panel
itself, which offers to add it as an icon or another matching widget.

BUG: 389613
---
 applets/taskmanager/CMakeLists.txt |  1 +
 applets/taskmanager/backend.cpp    | 27 +++++++++++++++++++++++++++
 applets/taskmanager/backend.h      |  3 +++
 applets/taskmanager/qml/main.qml   |  4 ++++
 4 files changed, 35 insertions(+)

diff --git a/applets/taskmanager/CMakeLists.txt b/applets/taskmanager/CMakeLists.txt
index 64f548de35..f020197548 100644
--- a/applets/taskmanager/CMakeLists.txt
+++ b/applets/taskmanager/CMakeLists.txt
@@ -47,6 +47,7 @@ target_link_libraries(org.kde.plasma.taskmanager PRIVATE
                       Qt::Quick
                       Plasma::Activities
                       Plasma::ActivitiesStats
+                      Plasma::PlasmaQuick
                       KF6::ConfigGui
                       KF6::GlobalAccel
                       KF6::I18n
diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..5b509e2799 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -29,6 +29,7 @@
 #include <QApplication>
 #include <QJsonArray>
 #include <QMenu>
+#include <QMimeData>
 #include <QQuickItem>
 #include <QQuickWindow>
 #include <QStandardPaths>
@@ -39,6 +40,9 @@

 #include <mutex>

+#include <Plasma/Containment>
+#include <PlasmaQuick/AppletQuickItem>
+
 #include <PlasmaActivities/Consumer>
 #include <PlasmaActivities/Stats/Cleaning>
 #include <PlasmaActivities/Stats/ResultSet>
@@ -541,6 +545,29 @@ bool Backend::isApplication(const QUrl &url) const
     return desktopFile.hasApplicationType();
 }

+void Backend::forwardUrlsToContainment(Plasma::Applet *applet, QQuickItem *item, const QPointF &pos, const QList<QUrl> &urls) const
+{
+    if (!applet || !applet->containment() || !item) {
+        return;
+    }
+
+    QQuickItem *containmentItem = PlasmaQuick::AppletQuickItem::itemForApplet(applet->containment());
+    if (!containmentItem) {
+        return;
+    }
+
+    const QPoint containmentPos = containmentItem->mapFromItem(item, pos).toPoint();
+
+    QMimeData mimeData;
+    mimeData.setUrls(urls);
+    QMetaObject::invokeMethod(containmentItem,
+                              "processMimeData",
+                              Qt::DirectConnection,
+                              Q_ARG(QMimeData *, &mimeData),
+                              Q_ARG(int, containmentPos.x()),
+                              Q_ARG(int, containmentPos.y()));
+}
+
 qint64 Backend::parentPid(qint64 pid) const
 {
     KSysGuard::Processes procs;
diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..22a76d7c21 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -7,6 +7,7 @@
 #pragma once

 #include <KConfigWatcher>
+#include <Plasma/Applet>

 #include <QAction>
 #include <QObject>
@@ -63,6 +64,8 @@ public:

     Q_INVOKABLE bool isApplication(const QUrl &url) const;

+    Q_INVOKABLE void forwardUrlsToContainment(Plasma::Applet *applet, QQuickItem *item, const QPointF &pos, const QList<QUrl> &urls) const;
+
     Q_INVOKABLE qint64 parentPid(qint64 pid) const;

     Q_INVOKABLE static QUrl tryDecodeApplicationsUrl(const QUrl &launcherUrl);
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..ca5ce5ee34 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -413,7 +413,11 @@ PlasmoidItem {
                     return;
                 }

+                // Dropping anything else on empty space lets the containment handle it, e.g. creating an icon on the panel.
                 if (!hoveredItem) {
+                    if (!Plasmoid.containment.immutable) {
+                        tasks.backend.forwardUrlsToContainment(Plasmoid, mouseHandler, Qt.point(drag.x, drag.y), urls);
+                    }
                     return;
                 }

